"""Karnataka PUC chemistry practicals with their own benches or kits: sols,
melting and boiling points, the Daniell cell, functional-group tests and
Lassaigne's test. Written for KINETIX; reviewed=False until a teacher checks."""


def add(lab, W, Q):
    puc1 = dict(subject='Chemistry', domain='chemistry', levels=[11], curricula=['ka-puc', 'cbse', 'ncert'])
    puc2 = dict(subject='Chemistry', domain='chemistry', levels=[12], curricula=['ka-puc', 'cbse', 'ncert'])
    TUBES = W('Test tubes, stand and holder', 'परखनलियाँ, स्टैंड और होल्डर', 'ಪರೀಕ್ಷಾ ನಳಿಕೆಗಳು, ಸ್ಟ್ಯಾಂಡ್ ಮತ್ತು ಹಿಡಿಕೆ')
    BURNER = W('Bunsen burner or spirit lamp', 'बुन्सन बर्नर या स्पिरिट लैंप', 'ಬನ್ಸೆನ್ ಬರ್ನರ್ ಅಥವಾ ಸ್ಪಿರಿಟ್ ದೀಪ')
    SMALL = W('Use small quantities and add reagents drop by drop.', 'कम मात्रा लें और अभिकर्मक बूँद-बूँद डालें।', 'ಕಡಿಮೆ ಪ್ರಮಾಣ ಬಳಸಿ, ಕಾರಕಗಳನ್ನು ಹನಿ ಹನಿಯಾಗಿ ಸೇರಿಸಿ.')
    POINT = W('Point the mouth of a heated tube away from everyone.', 'गर्म परखनली का मुँह सबसे दूर रखें।', 'ಬಿಸಿಯಾದ ನಳಿಕೆಯ ಬಾಯಿಯನ್ನು ಎಲ್ಲರಿಂದ ದೂರ ಇಡಿ.')

    lab(id='preparation-of-sols', bench='colloid', **puc2,
        keywords=['colloids', 'sol', 'lyophilic', 'lyophobic', 'tyndall effect', 'ferric hydroxide sol', 'starch sol', 'surface chemistry', 'coagulation'],
        title=W('Preparation of lyophilic and lyophobic sols', 'द्रवरागी और द्रवविरागी सॉल बनाना', 'ದ್ರವಪ್ರಿಯ ಮತ್ತು ದ್ರವದ್ವೇಷಿ ಸಾಲ್ ತಯಾರಿಕೆ'),
        summary=W('Make starch, gum and albumin sols and ferric and aluminium hydroxide sols; see the Tyndall effect and test each with a little salt.', 'स्टार्च, गोंद और एल्ब्यूमिन सॉल तथा फ़ेरिक और ऐलुमिनियम हाइड्रॉक्साइड सॉल बनाएँ; टिंडल प्रभाव देखें और प्रत्येक को थोड़े लवण से जाँचें।', 'ಪಿಷ್ಟ, ಅಂಟು ಮತ್ತು ಆಲ್ಬುಮಿನ್ ಸಾಲ್‌ಗಳು ಹಾಗೂ ಫೆರಿಕ್ ಮತ್ತು ಅಲ್ಯೂಮಿನಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್ ಸಾಲ್‌ಗಳನ್ನು ತಯಾರಿಸಿ; ಟಿಂಡಾಲ್ ಪರಿಣಾಮ ನೋಡಿ, ಪ್ರತಿಯೊಂದನ್ನು ಸ್ವಲ್ಪ ಉಪ್ಪಿನಿಂದ ಪರೀಕ್ಷಿಸಿ.'),
        aim=W('To prepare lyophilic sols of starch, gum arabic and egg albumin and lyophobic sols of ferric hydroxide and aluminium hydroxide, and to compare their properties.', 'स्टार्च, गोंद अरबी और अंडे के एल्ब्यूमिन के द्रवरागी सॉल तथा फ़ेरिक हाइड्रॉक्साइड और ऐलुमिनियम हाइड्रॉक्साइड के द्रवविरागी सॉल बनाना और उनके गुणों की तुलना करना।', 'ಪಿಷ್ಟ, ಗಮ್ ಅರೇಬಿಕ್ ಮತ್ತು ಮೊಟ್ಟೆ ಆಲ್ಬುಮಿನ್‌ನ ದ್ರವಪ್ರಿಯ ಸಾಲ್‌ಗಳು ಹಾಗೂ ಫೆರಿಕ್ ಹೈಡ್ರಾಕ್ಸೈಡ್ ಮತ್ತು ಅಲ್ಯೂಮಿನಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್‌ನ ದ್ರವದ್ವೇಷಿ ಸಾಲ್‌ಗಳನ್ನು ತಯಾರಿಸಿ ಗುಣಗಳನ್ನು ಹೋಲಿಸುವುದು.'),
        principle=W('Lyophilic substances pass into colloidal form simply on warming with water and are stable. Lyophobic sols need special methods, such as hydrolysis: FeCl₃ + 3H₂O → Fe(OH)₃ (sol) + 3HCl in boiling water. Colloidal particles (1–1000 nm) scatter light (Tyndall effect); a little electrolyte coagulates a lyophobic sol.', 'द्रवरागी पदार्थ पानी के साथ गर्म करने पर ही कोलॉइडी रूप में आ जाते हैं और स्थायी होते हैं। द्रवविरागी सॉल के लिए विशेष विधियाँ चाहिए, जैसे जल-अपघटन: उबलते पानी में FeCl₃ + 3H₂O → Fe(OH)₃ (सॉल) + 3HCl. कोलॉइडी कण (1–1000 nm) प्रकाश प्रकीर्णित करते हैं (टिंडल प्रभाव); थोड़ा विद्युत-अपघट्य द्रवविरागी सॉल को स्कंदित कर देता है।', 'ದ್ರವಪ್ರಿಯ ವಸ್ತುಗಳು ನೀರಿನೊಂದಿಗೆ ಬಿಸಿಮಾಡಿದರೆ ಸಾಕು, ಕಲಿಲ ರೂಪಕ್ಕೆ ಬಂದು ಸ್ಥಿರವಾಗಿರುತ್ತವೆ. ದ್ರವದ್ವೇಷಿ ಸಾಲ್‌ಗಳಿಗೆ ವಿಶೇಷ ವಿಧಾನ ಬೇಕು, ಉದಾ. ಜಲವಿಭಜನೆ: ಕುದಿಯುವ ನೀರಿನಲ್ಲಿ FeCl₃ + 3H₂O → Fe(OH)₃ (ಸಾಲ್) + 3HCl. ಕಲಿಲ ಕಣಗಳು (1–1000 nm) ಬೆಳಕನ್ನು ಚದುರಿಸುತ್ತವೆ (ಟಿಂಡಾಲ್ ಪರಿಣಾಮ); ಸ್ವಲ್ಪ ವಿದ್ಯುದ್ವಿಭಾಜ್ಯ ದ್ರವದ್ವೇಷಿ ಸಾಲನ್ನು ಹೆಪ್ಪುಗಟ್ಟಿಸುತ್ತದೆ.'),
        apparatus=[W('Beakers, glass rod and funnel', 'बीकर, काँच की छड़ और कीप', 'ಬೀಕರ್‌ಗಳು, ಗಾಜಿನ ಕಡ್ಡಿ ಮತ್ತು ಆಲಿಕೆ'), BURNER, W('Starch, gum arabic, egg, 2% FeCl₃, AlCl₃, NaCl solution', 'स्टार्च, गोंद अरबी, अंडा, 2% FeCl₃, AlCl₃, NaCl विलयन', 'ಪಿಷ್ಟ, ಗಮ್ ಅರೇಬಿಕ್, ಮೊಟ್ಟೆ, 2% FeCl₃, AlCl₃, NaCl ದ್ರಾವಣ'), W('Torch', 'टॉर्च', 'ಟಾರ್ಚ್')],
        steps=[W('Starch: make a paste of 0.5 g starch with a little water and pour it into 100 mL boiling water, stirring.', 'स्टार्च: 0.5 g स्टार्च का थोड़े पानी में पेस्ट बनाकर हिलाते हुए 100 mL उबलते पानी में डालें।', 'ಪಿಷ್ಟ: 0.5 g ಪಿಷ್ಟವನ್ನು ಸ್ವಲ್ಪ ನೀರಿನಲ್ಲಿ ಪೇಸ್ಟ್ ಮಾಡಿ ಕಲಕುತ್ತಾ 100 mL ಕುದಿಯುವ ನೀರಿಗೆ ಸುರಿಯಿರಿ.'),
               W('Gum and albumin: stir gum arabic into warm water; shake egg white with 5% NaCl solution.', 'गोंद और एल्ब्यूमिन: गोंद अरबी को गुनगुने पानी में घोलें; अंडे की सफ़ेदी को 5% NaCl विलयन में हिलाएँ।', 'ಅಂಟು ಮತ್ತು ಆಲ್ಬುಮಿನ್: ಗಮ್ ಅರೇಬಿಕನ್ನು ಉಗುರುಬೆಚ್ಚಗಿನ ನೀರಿನಲ್ಲಿ ಕಲಕಿ; ಮೊಟ್ಟೆಯ ಬಿಳಿಯನ್ನು 5% NaCl ದ್ರಾವಣದೊಂದಿಗೆ ಅಲುಗಾಡಿಸಿ.'),
               W('Ferric hydroxide: add 2% FeCl₃ drop by drop to 100 mL boiling water until it turns deep reddish-brown.', 'फ़ेरिक हाइड्रॉक्साइड: 100 mL उबलते पानी में 2% FeCl₃ बूँद-बूँद डालें जब तक गहरा लाल-भूरा न हो जाए।', 'ಫೆರಿಕ್ ಹೈಡ್ರಾಕ್ಸೈಡ್: 100 mL ಕುದಿಯುವ ನೀರಿಗೆ ಗಾಢ ಕೆಂಪು-ಕಂದು ಆಗುವವರೆಗೆ 2% FeCl₃ ಹನಿ ಹನಿಯಾಗಿ ಸೇರಿಸಿ.'),
               W('Shine a torch through each sol and through a salt solution; look for the beam’s path.', 'प्रत्येक सॉल और एक लवण विलयन में टॉर्च चमकाएँ; किरण-पथ देखें।', 'ಪ್ರತಿ ಸಾಲ್ ಮತ್ತು ಉಪ್ಪಿನ ದ್ರಾವಣದ ಮೂಲಕ ಟಾರ್ಚ್ ಬೆಳಗಿಸಿ; ಕಿರಣದ ಹಾದಿ ನೋಡಿ.'),
               W('Add a few drops of NaCl solution to each sol and note which coagulate.', 'प्रत्येक सॉल में NaCl विलयन की कुछ बूँदें डालें और देखें कौन स्कंदित होते हैं।', 'ಪ್ರತಿ ಸಾಲ್‌ಗೆ ಕೆಲವು ಹನಿ NaCl ದ್ರಾವಣ ಸೇರಿಸಿ ಯಾವುದು ಹೆಪ್ಪುಗಟ್ಟುತ್ತದೆ ಗಮನಿಸಿ.')],
        precautions=[W('Use clean glassware rinsed with distilled water: impurities coagulate sols.', 'आसुत जल से धुले साफ़ काँच के बर्तन लें: अशुद्धियाँ सॉल को स्कंदित करती हैं।', 'ಬಟ್ಟಿ ಇಳಿಸಿದ ನೀರಿನಿಂದ ತೊಳೆದ ಸ್ವಚ್ಛ ಗಾಜಿನ ಪಾತ್ರೆ ಬಳಸಿ: ಕಲ್ಮಶಗಳು ಸಾಲನ್ನು ಹೆಪ್ಪುಗಟ್ಟಿಸುತ್ತವೆ.'), W('Add FeCl₃ slowly to water that is actually boiling.', 'FeCl₃ को वास्तव में उबलते पानी में धीरे-धीरे डालें।', 'FeCl₃ ಅನ್ನು ನಿಜವಾಗಿ ಕುದಿಯುತ್ತಿರುವ ನೀರಿಗೆ ನಿಧಾನವಾಗಿ ಸೇರಿಸಿ.'), W('Do not over-boil the albumin sol: it coagulates.', 'एल्ब्यूमिन सॉल को अधिक न उबालें: वह जम जाता है।', 'ಆಲ್ಬುಮಿನ್ ಸಾಲನ್ನು ಹೆಚ್ಚು ಕುದಿಸಬೇಡಿ: ಅದು ಹೆಪ್ಪುಗಟ್ಟುತ್ತದೆ.')],
        conclusion=W('All the sols show the Tyndall effect and the true solution does not. The lyophobic sols coagulate with a little electrolyte while the lyophilic ones stay stable.', 'सभी सॉल टिंडल प्रभाव दिखाते हैं और वास्तविक विलयन नहीं। द्रवविरागी सॉल थोड़े विद्युत-अपघट्य से स्कंदित होते हैं जबकि द्रवरागी स्थायी रहते हैं।', 'ಎಲ್ಲಾ ಸಾಲ್‌ಗಳು ಟಿಂಡಾಲ್ ಪರಿಣಾಮ ತೋರುತ್ತವೆ, ನಿಜ ದ್ರಾವಣ ತೋರುವುದಿಲ್ಲ. ದ್ರವದ್ವೇಷಿ ಸಾಲ್‌ಗಳು ಸ್ವಲ್ಪ ವಿದ್ಯುದ್ವಿಭಾಜ್ಯದಿಂದ ಹೆಪ್ಪುಗಟ್ಟುತ್ತವೆ, ದ್ರವಪ್ರಿಯಗಳು ಸ್ಥಿರವಾಗಿರುತ್ತವೆ.'),
        viva=[Q(W('What is the Tyndall effect?', 'टिंडल प्रभाव क्या है?', 'ಟಿಂಡಾಲ್ ಪರಿಣಾಮ ಎಂದರೇನು?'), W('Scattering of light by colloidal particles, which makes the beam’s path visible.', 'कोलॉइडी कणों द्वारा प्रकाश का प्रकीर्णन, जिससे किरण-पथ दिखाई देता है।', 'ಕಲಿಲ ಕಣಗಳಿಂದ ಬೆಳಕಿನ ಚದುರುವಿಕೆ, ಇದರಿಂದ ಕಿರಣದ ಹಾದಿ ಕಾಣುತ್ತದೆ.')),
              Q(W('What charge does a ferric hydroxide sol carry?', 'फ़ेरिक हाइड्रॉक्साइड सॉल पर कौन सा आवेश होता है?', 'ಫೆರಿಕ್ ಹೈಡ್ರಾಕ್ಸೈಡ್ ಸಾಲ್ ಮೇಲೆ ಯಾವ ಆವೇಶ?'), W('Positive: it adsorbs Fe³⁺ ions.', 'धनात्मक: यह Fe³⁺ आयन अधिशोषित करता है।', 'ಧನಾತ್ಮಕ: ಅದು Fe³⁺ ಅಯಾನುಗಳನ್ನು ಅಧಿಶೋಷಿಸುತ್ತದೆ.')),
              Q(W('Why are lyophilic sols more stable?', 'द्रवरागी सॉल अधिक स्थायी क्यों होते हैं?', 'ದ್ರವಪ್ರಿಯ ಸಾಲ್‌ಗಳು ಹೆಚ್ಚು ಸ್ಥಿರ ಏಕೆ?'), W('Their particles are surrounded by a layer of solvent (solvation) as well as charge.', 'उनके कण आवेश के साथ-साथ विलायक की परत (विलायकन) से घिरे रहते हैं।', 'ಅವುಗಳ ಕಣಗಳು ಆವೇಶದ ಜೊತೆಗೆ ದ್ರಾವಕದ ಪದರದಿಂದ (ದ್ರಾವಣೀಕರಣ) ಸುತ್ತುವರಿದಿವೆ.')),
              Q(W('State the Hardy–Schulze rule.', 'हार्डी–शुल्ज़े नियम बताइए।', 'ಹಾರ್ಡಿ–ಶುಲ್ಜ್ ನಿಯಮ ತಿಳಿಸಿ.'), W('The greater the charge on the coagulating ion, the stronger its coagulating power.', 'स्कंदक आयन पर आवेश जितना अधिक, उसकी स्कंदन क्षमता उतनी अधिक।', 'ಹೆಪ್ಪುಗಟ್ಟಿಸುವ ಅಯಾನಿನ ಆವೇಶ ಹೆಚ್ಚಿದಷ್ಟೂ ಅದರ ಹೆಪ್ಪುಗಟ್ಟಿಸುವ ಶಕ್ತಿ ಹೆಚ್ಚು.')),
              Q(W('Give the size range of colloidal particles.', 'कोलॉइडी कणों का आकार परिसर बताइए।', 'ಕಲಿಲ ಕಣಗಳ ಗಾತ್ರ ವ್ಯಾಪ್ತಿ ತಿಳಿಸಿ.'), W('About 1 nm to 1000 nm.', 'लगभग 1 nm से 1000 nm.', 'ಸುಮಾರು 1 nm ನಿಂದ 1000 nm.'))])

    MP_APP = [W('Thiele tube with liquid paraffin', 'तरल पैराफ़िन सहित थीले नली', 'ದ್ರವ ಪ್ಯಾರಾಫಿನ್ ಸಹಿತ ಥೀಲೆ ನಳಿಕೆ'), W('Thermometer (0–200 °C)', 'तापमापी (0–200 °C)', 'ತಾಪಮಾಪಕ (0–200 °C)'), W('Capillary tubes and a rubber band', 'केशिका नलियाँ और रबर बैंड', 'ಲೋಮನಾಳಗಳು ಮತ್ತು ರಬ್ಬರ್ ಬ್ಯಾಂಡ್'), BURNER]
    lab(id='melting-point', bench='melting-point', setup={'task': 'mp'}, **puc1,
        keywords=['melting point', 'organic compound', 'purity', 'capillary', 'thiele tube', 'organic chemistry some basic principles and techniques', 'naphthalene'],
        title=W('Melting point of an organic compound', 'कार्बनिक यौगिक का गलनांक', 'ಸಾವಯವ ಸಂಯುಕ್ತದ ದ್ರವನ ಬಿಂದು'),
        summary=W('Heat a capillary of the compound slowly in a Thiele tube and note the temperature at which it melts sharply.', 'यौगिक वाली केशिका को थीले नली में धीरे-धीरे गर्म करें और वह ताप लिखें जिस पर वह तीव्रता से पिघलती है।', 'ಸಂಯುಕ್ತದ ಲೋಮನಾಳವನ್ನು ಥೀಲೆ ನಳಿಕೆಯಲ್ಲಿ ನಿಧಾನವಾಗಿ ಬಿಸಿಮಾಡಿ, ಅದು ತೀಕ್ಷ್ಣವಾಗಿ ಕರಗುವ ತಾಪ ಗಮನಿಸಿ.'),
        aim=W('To determine the melting point of a given organic compound.', 'दिए गए कार्बनिक यौगिक का गलनांक ज्ञात करना।', 'ನೀಡಿದ ಸಾವಯವ ಸಂಯುಕ್ತದ ದ್ರವನ ಬಿಂದು ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('A pure crystalline solid melts sharply at a fixed temperature, within about 1 °C. Impurities lower the melting point and spread it over a range, so the melting point both identifies a compound and tests its purity.', 'शुद्ध क्रिस्टलीय ठोस एक निश्चित ताप पर, लगभग 1 °C के भीतर, तीव्रता से पिघलता है। अशुद्धियाँ गलनांक घटाती हैं और उसे एक परास में फैला देती हैं, इसलिए गलनांक यौगिक की पहचान और शुद्धता दोनों बताता है।', 'ಶುದ್ಧ ಸ್ಫಟಿಕ ಘನ ನಿಗದಿತ ತಾಪದಲ್ಲಿ, ಸುಮಾರು 1 °C ಒಳಗೆ, ತೀಕ್ಷ್ಣವಾಗಿ ಕರಗುತ್ತದೆ. ಕಲ್ಮಶಗಳು ದ್ರವನ ಬಿಂದು ಇಳಿಸಿ ವ್ಯಾಪ್ತಿಗೆ ಹರಡುತ್ತವೆ; ಹಾಗಾಗಿ ದ್ರವನ ಬಿಂದು ಸಂಯುಕ್ತವನ್ನು ಗುರುತಿಸುತ್ತದೆ ಮತ್ತು ಶುದ್ಧತೆ ಪರೀಕ್ಷಿಸುತ್ತದೆ.'),
        apparatus=MP_APP,
        steps=[W('Seal one end of a capillary and fill 2–3 mm of the powdered compound, tapping it down.', 'केशिका का एक सिरा बंद करें और उसमें 2–3 mm पिसा यौगिक भरकर ठोकें।', 'ಲೋಮನಾಳದ ಒಂದು ತುದಿ ಮುಚ್ಚಿ 2–3 mm ಪುಡಿ ಸಂಯುಕ್ತ ತುಂಬಿ ತಟ್ಟಿ ಕೆಳಗಿಳಿಸಿ.'),
               W('Tie it to the thermometer so the compound is beside the bulb, and dip both in the Thiele tube.', 'इसे तापमापी से बाँधें ताकि यौगिक बल्ब के पास रहे, और दोनों को थीले नली में डुबोएँ।', 'ಸಂಯುಕ್ತ ಬಲ್ಬಿನ ಪಕ್ಕದಲ್ಲಿರುವಂತೆ ತಾಪಮಾಪಕಕ್ಕೆ ಕಟ್ಟಿ, ಎರಡನ್ನೂ ಥೀಲೆ ನಳಿಕೆಯಲ್ಲಿ ಮುಳುಗಿಸಿ.'),
               W('Heat the side arm, quickly at first and then about 2 °C a minute near the expected melting point.', 'पार्श्व भुजा को गर्म करें, पहले तेज़ी से और अपेक्षित गलनांक के पास लगभग 2 °C प्रति मिनट।', 'ಪಕ್ಕದ ತೋಳನ್ನು ಬಿಸಿಮಾಡಿ, ಮೊದಲು ವೇಗವಾಗಿ, ನಿರೀಕ್ಷಿತ ದ್ರವನ ಬಿಂದು ಹತ್ತಿರ ನಿಮಿಷಕ್ಕೆ ಸುಮಾರು 2 °C.'),
               W('Note the temperature when the solid just melts to a clear liquid.', 'जब ठोस बस पिघलकर साफ़ द्रव बने, तब ताप लिखें।', 'ಘನ ಕರಗಿ ಸ್ಪಷ್ಟ ದ್ರವವಾದಾಗ ತಾಪ ಬರೆಯಿರಿ.'),
               W('Repeat with a fresh capillary and take the mean.', 'नई केशिका से दोहराएँ और माध्य लें।', 'ಹೊಸ ಲೋಮನಾಳದಿಂದ ಪುನರಾವರ್ತಿಸಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ.')],
        precautions=[W('Heat slowly near the melting point.', 'गलनांक के पास धीरे-धीरे गर्म करें।', 'ದ್ರವನ ಬಿಂದು ಹತ್ತಿರ ನಿಧಾನವಾಗಿ ಬಿಸಿಮಾಡಿ.'), W('Keep the compound level with the thermometer bulb.', 'यौगिक को तापमापी बल्ब के स्तर पर रखें।', 'ಸಂಯುಕ್ತವನ್ನು ತಾಪಮಾಪಕ ಬಲ್ಬಿನ ಮಟ್ಟದಲ್ಲಿಡಿ.'), W('Use a fresh capillary for each reading.', 'हर पाठ्यांक के लिए नई केशिका लें।', 'ಪ್ರತಿ ಓದಿಗೆ ಹೊಸ ಲೋಮನಾಳ ಬಳಸಿ.')],
        conclusion=W('The compound melts sharply within a degree of the literature value, which identifies it and shows it is pure.', 'यौगिक साहित्य मान के एक डिग्री के भीतर तीव्रता से पिघलता है, जिससे उसकी पहचान होती है और वह शुद्ध सिद्ध होता है।', 'ಸಂಯುಕ್ತ ಸಾಹಿತ್ಯ ಮೌಲ್ಯದ ಒಂದು ಡಿಗ್ರಿ ಒಳಗೆ ತೀಕ್ಷ್ಣವಾಗಿ ಕರಗುತ್ತದೆ; ಇದು ಅದನ್ನು ಗುರುತಿಸಿ ಶುದ್ಧವೆಂದು ತೋರಿಸುತ್ತದೆ.'),
        viva=[Q(W('Why is liquid paraffin used in the bath?', 'बाथ में तरल पैराफ़िन क्यों लेते हैं?', 'ಸ್ನಾನಪಾತ್ರೆಯಲ್ಲಿ ದ್ರವ ಪ್ಯಾರಾಫಿನ್ ಏಕೆ?'), W('It has a high boiling point and is not flammable at these temperatures.', 'इसका क्वथनांक ऊँचा है और इन तापों पर यह ज्वलनशील नहीं है।', 'ಅದರ ಕುದಿಬಿಂದು ಹೆಚ್ಚು; ಈ ತಾಪಗಳಲ್ಲಿ ಉರಿಯುವುದಿಲ್ಲ.')),
              Q(W('Why is a Thiele tube shaped as it is?', 'थीले नली का आकार ऐसा क्यों है?', 'ಥೀಲೆ ನಳಿಕೆಯ ಆಕಾರ ಹಾಗೇಕೆ?'), W('Heating the side arm sets up convection that heats the bath evenly.', 'पार्श्व भुजा गर्म करने से संवहन होता है जो बाथ को समान रूप से गर्म करता है।', 'ಪಕ್ಕದ ತೋಳನ್ನು ಬಿಸಿಮಾಡಿದರೆ ಸಂವಹನದಿಂದ ಸ್ನಾನಪಾತ್ರೆ ಸಮವಾಗಿ ಬಿಸಿಯಾಗುತ್ತದೆ.')),
              Q(W('What does a melting range of 5 °C show?', '5 °C का गलन परास क्या दर्शाता है?', '5 °C ದ್ರವನ ವ್ಯಾಪ್ತಿ ಏನನ್ನು ತೋರಿಸುತ್ತದೆ?'), W('That the sample is impure.', 'कि नमूना अशुद्ध है।', 'ಮಾದರಿ ಅಶುದ್ಧ ಎಂದು.')),
              Q(W('What is a mixed melting point test?', 'मिश्रित गलनांक परीक्षण क्या है?', 'ಮಿಶ್ರ ದ್ರವನ ಬಿಂದು ಪರೀಕ್ಷೆ ಎಂದರೇನು?'), W('Mixing with a known pure sample: no lowering means the two are the same compound.', 'ज्ञात शुद्ध नमूने के साथ मिलाना: गलनांक न घटे तो दोनों एक ही यौगिक हैं।', 'ತಿಳಿದ ಶುದ್ಧ ಮಾದರಿಯೊಂದಿಗೆ ಬೆರೆಸುವುದು: ಇಳಿಕೆ ಇಲ್ಲದಿದ್ದರೆ ಎರಡೂ ಒಂದೇ ಸಂಯುಕ್ತ.')),
              Q(W('Give the melting point of naphthalene.', 'नैफ़्थलीन का गलनांक बताइए।', 'ನ್ಯಾಫ್ತಲೀನ್‌ನ ದ್ರವನ ಬಿಂದು ತಿಳಿಸಿ.'), W('About 80 °C.', 'लगभग 80 °C.', 'ಸುಮಾರು 80 °C.'))])

    lab(id='boiling-point', bench='melting-point', setup={'task': 'bp', 'compound': 'ethanol'}, **puc1,
        keywords=['boiling point', 'organic liquid', 'siwoloboff', 'fusion tube', 'organic chemistry some basic principles and techniques', 'purity'],
        title=W('Boiling point of an organic liquid', 'कार्बनिक द्रव का क्वथनांक', 'ಸಾವಯವ ದ್ರವದ ಕುದಿಬಿಂದು'),
        summary=W('Heat a fusion tube with the liquid and an inverted capillary; the boiling point is where a rapid stream of bubbles appears.', 'द्रव और उलटी केशिका वाली फ़्यूज़न नली गर्म करें; क्वथनांक वह है जहाँ बुलबुलों की तेज़ धारा निकलती है।', 'ದ್ರವ ಮತ್ತು ತಲೆಕೆಳಗಾದ ಲೋಮನಾಳವಿರುವ ಫ್ಯೂಷನ್ ನಳಿಕೆ ಬಿಸಿಮಾಡಿ; ಗುಳ್ಳೆಗಳ ವೇಗದ ಧಾರೆ ಬರುವಲ್ಲಿ ಕುದಿಬಿಂದು.'),
        aim=W('To determine the boiling point of a given organic liquid.', 'दिए गए कार्बनिक द्रव का क्वथनांक ज्ञात करना।', 'ನೀಡಿದ ಸಾವಯವ ದ್ರವದ ಕುದಿಬಿಂದು ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('A liquid boils when its vapour pressure equals the atmospheric pressure. Air in the inverted capillary expands on heating; at the boiling point vapour escapes as a rapid, continuous stream of bubbles.', 'द्रव तब उबलता है जब उसका वाष्प दाब वायुमंडलीय दाब के बराबर हो। उलटी केशिका की वायु गर्म होने पर फैलती है; क्वथनांक पर वाष्प बुलबुलों की तेज़, लगातार धारा के रूप में निकलती है।', 'ದ್ರವದ ಆವಿ ಒತ್ತಡ ವಾತಾವರಣ ಒತ್ತಡಕ್ಕೆ ಸಮವಾದಾಗ ಅದು ಕುದಿಯುತ್ತದೆ. ತಲೆಕೆಳಗಾದ ಲೋಮನಾಳದ ಗಾಳಿ ಬಿಸಿಯಾದಾಗ ಹಿಗ್ಗುತ್ತದೆ; ಕುದಿಬಿಂದುವಿನಲ್ಲಿ ಆವಿ ವೇಗದ, ನಿರಂತರ ಗುಳ್ಳೆಗಳ ಧಾರೆಯಾಗಿ ಹೊರಬರುತ್ತದೆ.'),
        apparatus=[W('Fusion tube and capillary', 'फ़्यूज़न नली और केशिका', 'ಫ್ಯೂಷನ್ ನಳಿಕೆ ಮತ್ತು ಲೋಮನಾಳ')] + MP_APP[:2] + [BURNER],
        steps=[W('Put 1–2 mL of the liquid in a fusion tube and drop in a capillary sealed at the top, open end down.', 'फ़्यूज़न नली में 1–2 mL द्रव लें और ऊपर से बंद केशिका का खुला सिरा नीचे करके डालें।', 'ಫ್ಯೂಷನ್ ನಳಿಕೆಯಲ್ಲಿ 1–2 mL ದ್ರವ ಹಾಕಿ, ಮೇಲೆ ಮುಚ್ಚಿದ ಲೋಮನಾಳವನ್ನು ತೆರೆದ ತುದಿ ಕೆಳಗೆ ಮಾಡಿ ಹಾಕಿ.'),
               W('Tie the tube to the thermometer and heat it in the bath.', 'नली को तापमापी से बाँधें और बाथ में गर्म करें।', 'ನಳಿಕೆಯನ್ನು ತಾಪಮಾಪಕಕ್ಕೆ ಕಟ್ಟಿ ಸ್ನಾನಪಾತ್ರೆಯಲ್ಲಿ ಬಿಸಿಮಾಡಿ.'),
               W('Watch the capillary: slow bubbles first, then a rapid steady stream.', 'केशिका देखें: पहले धीमे बुलबुले, फिर तेज़ लगातार धारा।', 'ಲೋಮನಾಳ ಗಮನಿಸಿ: ಮೊದಲು ನಿಧಾನ ಗುಳ್ಳೆಗಳು, ನಂತರ ವೇಗದ ನಿರಂತರ ಧಾರೆ.'),
               W('Note the temperature of the rapid stream; let it cool and note when bubbling stops.', 'तेज़ धारा का ताप लिखें; ठंडा होने दें और बुलबुले रुकने पर ताप लिखें।', 'ವೇಗದ ಧಾರೆಯ ತಾಪ ಬರೆಯಿರಿ; ತಣ್ಣಗಾಗಲು ಬಿಟ್ಟು ಗುಳ್ಳೆ ನಿಂತಾಗ ತಾಪ ಬರೆಯಿರಿ.'),
               W('Take the mean of the two temperatures.', 'दोनों तापों का माध्य लें।', 'ಎರಡು ತಾಪಗಳ ಸರಾಸರಿ ತೆಗೆಯಿರಿ.')],
        precautions=[W('Keep flammable liquids away from the open flame; heat in a bath only.', 'ज्वलनशील द्रवों को खुली ज्वाला से दूर रखें; केवल बाथ में गर्म करें।', 'ಉರಿಯುವ ದ್ರವಗಳನ್ನು ತೆರೆದ ಜ್ವಾಲೆಯಿಂದ ದೂರವಿಡಿ; ಸ್ನಾನಪಾತ್ರೆಯಲ್ಲಿ ಮಾತ್ರ ಬಿಸಿಮಾಡಿ.'), W('Heat slowly near the boiling point.', 'क्वथनांक के पास धीरे-धीरे गर्म करें।', 'ಕುದಿಬಿಂದು ಹತ್ತಿರ ನಿಧಾನವಾಗಿ ಬಿಸಿಮಾಡಿ.')],
        conclusion=W('The rapid stream of bubbles appears within a degree of the literature boiling point, which identifies the liquid.', 'बुलबुलों की तेज़ धारा साहित्य क्वथनांक के एक डिग्री के भीतर दिखती है, जिससे द्रव की पहचान होती है।', 'ಗುಳ್ಳೆಗಳ ವೇಗದ ಧಾರೆ ಸಾಹಿತ್ಯ ಕುದಿಬಿಂದುವಿನ ಒಂದು ಡಿಗ್ರಿ ಒಳಗೆ ಕಾಣುತ್ತದೆ; ಇದು ದ್ರವವನ್ನು ಗುರುತಿಸುತ್ತದೆ.'),
        viva=[Q(W('Define boiling point.', 'क्वथनांक की परिभाषा दीजिए।', 'ಕುದಿಬಿಂದು ವ್ಯಾಖ್ಯಾನಿಸಿ.'), W('The temperature at which the vapour pressure equals the external pressure.', 'वह ताप जिस पर वाष्प दाब बाहरी दाब के बराबर हो।', 'ಆವಿ ಒತ್ತಡ ಬಾಹ್ಯ ಒತ್ತಡಕ್ಕೆ ಸಮವಾಗುವ ತಾಪ.')),
              Q(W('How does altitude affect the boiling point?', 'ऊँचाई क्वथनांक को कैसे प्रभावित करती है?', 'ಎತ್ತರ ಕುದಿಬಿಂದುವನ್ನು ಹೇಗೆ ಪ್ರಭಾವಿಸುತ್ತದೆ?'), W('It lowers it, because the air pressure is lower.', 'यह इसे घटाती है, क्योंकि वायुदाब कम होता है।', 'ಅದನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ, ಏಕೆಂದರೆ ಗಾಳಿಯ ಒತ್ತಡ ಕಡಿಮೆ.')),
              Q(W('What does a non-volatile impurity do?', 'अवाष्पशील अशुद्धि क्या करती है?', 'ಬಾಷ್ಪಶೀಲವಲ್ಲದ ಕಲ್ಮಶ ಏನು ಮಾಡುತ್ತದೆ?'), W('It raises the boiling point.', 'यह क्वथनांक बढ़ाती है।', 'ಅದು ಕುದಿಬಿಂದು ಹೆಚ್ಚಿಸುತ್ತದೆ.')),
              Q(W('Why does ethanol boil at a lower temperature than water?', 'एथेनॉल पानी से कम ताप पर क्यों उबलता है?', 'ಎಥನಾಲ್ ನೀರಿಗಿಂತ ಕಡಿಮೆ ತಾಪದಲ್ಲಿ ಏಕೆ ಕುದಿಯುತ್ತದೆ?'), W('Its hydrogen bonding is weaker, so its vapour pressure is higher.', 'इसका हाइड्रोजन आबंधन कमज़ोर है, अतः इसका वाष्प दाब अधिक है।', 'ಅದರ ಹೈಡ್ರೋಜನ್ ಬಂಧ ದುರ್ಬಲ, ಹಾಗಾಗಿ ಆವಿ ಒತ್ತಡ ಹೆಚ್ಚು.')),
              Q(W('Why is the capillary sealed at its upper end?', 'केशिका ऊपरी सिरे पर बंद क्यों होती है?', 'ಲೋಮನಾಳ ಮೇಲ್ತುದಿಯಲ್ಲಿ ಮುಚ್ಚಿರುವುದೇಕೆ?'), W('To trap air, whose escape as bubbles signals boiling.', 'वायु रोकने के लिए, जिसके बुलबुले बनकर निकलने से उबलना पता चलता है।', 'ಗಾಳಿಯನ್ನು ಬಂಧಿಸಲು; ಅದು ಗುಳ್ಳೆಯಾಗಿ ಹೊರಬರುವುದು ಕುದಿತವನ್ನು ಸೂಚಿಸುತ್ತದೆ.'))])

    lab(id='daniell-cell-emf', bench='daniell-cell', **puc2,
        keywords=['electrochemistry', 'daniell cell', 'nernst equation', 'emf', 'cell potential', 'concentration', 'salt bridge', 'galvanic cell'],
        title=W('EMF of a Daniell cell and the Nernst equation', 'डेनियल सेल का विद्युत वाहक बल और नर्न्स्ट समीकरण', 'ಡೇನಿಯಲ್ ಕೋಶದ emf ಮತ್ತು ನರ್ನ್‌ಸ್ಟ್ ಸಮೀಕರಣ'),
        summary=W('Change the concentrations of Zn²⁺ and Cu²⁺, read the cell’s EMF, and see it follow E = E° − 0.0296 log([Zn²⁺]/[Cu²⁺]).', 'Zn²⁺ और Cu²⁺ की सांद्रताएँ बदलें, सेल का EMF पढ़ें, और देखें कि वह E = E° − 0.0296 log([Zn²⁺]/[Cu²⁺]) का पालन करता है।', 'Zn²⁺ ಮತ್ತು Cu²⁺ ಸಾಂದ್ರತೆಗಳನ್ನು ಬದಲಿಸಿ, ಕೋಶದ emf ಓದಿ, ಅದು E = E° − 0.0296 log([Zn²⁺]/[Cu²⁺]) ಅನುಸರಿಸುವುದನ್ನು ನೋಡಿ.'),
        aim=W('To study the variation of the EMF of a Daniell cell with the concentrations of the electrolytes.', 'विद्युत-अपघट्यों की सांद्रता के साथ डेनियल सेल के विद्युत वाहक बल में परिवर्तन का अध्ययन करना।', 'ವಿದ್ಯುದ್ವಿಭಾಜ್ಯಗಳ ಸಾಂದ್ರತೆಯೊಂದಿಗೆ ಡೇನಿಯಲ್ ಕೋಶದ emf ಬದಲಾವಣೆ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('For Zn | Zn²⁺ || Cu²⁺ | Cu, E = E° − (2.303RT/2F) log([Zn²⁺]/[Cu²⁺]) = 1.10 − 0.0296 log([Zn²⁺]/[Cu²⁺]) V at 25 °C. E against log Q is a straight line of slope −0.0591/n.', 'Zn | Zn²⁺ || Cu²⁺ | Cu के लिए E = E° − (2.303RT/2F) log([Zn²⁺]/[Cu²⁺]) = 1.10 − 0.0296 log([Zn²⁺]/[Cu²⁺]) V, 25 °C पर। E और log Q का ग्राफ़ −0.0591/n प्रवणता की सीधी रेखा है।', 'Zn | Zn²⁺ || Cu²⁺ | Cu ಗೆ E = E° − (2.303RT/2F) log([Zn²⁺]/[Cu²⁺]) = 1.10 − 0.0296 log([Zn²⁺]/[Cu²⁺]) V, 25 °C ನಲ್ಲಿ. E ಮತ್ತು log Q ನಕ್ಷೆ −0.0591/n ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ.'),
        apparatus=[W('Zinc and copper strips', 'जिंक और ताँबे की पट्टियाँ', 'ಸತು ಮತ್ತು ತಾಮ್ರದ ಪಟ್ಟಿಗಳು'), W('ZnSO₄ and CuSO₄ solutions of several strengths', 'कई सांद्रताओं के ZnSO₄ और CuSO₄ विलयन', 'ಹಲವು ಸಾಂದ್ರತೆಯ ZnSO₄ ಮತ್ತು CuSO₄ ದ್ರಾವಣಗಳು'), W('Salt bridge (KCl in agar)', 'लवण सेतु (ऐगार में KCl)', 'ಉಪ್ಪಿನ ಸೇತುವೆ (ಅಗರ್‌ನಲ್ಲಿ KCl)'), W('High-resistance digital voltmeter', 'उच्च प्रतिरोध डिजिटल वोल्टमीटर', 'ಹೆಚ್ಚಿನ ರೋಧದ ಡಿಜಿಟಲ್ ವೋಲ್ಟ್‌ಮೀಟರ್')],
        steps=[W('Clean the strips with sandpaper and dip them in 1 M ZnSO₄ and 1 M CuSO₄.', 'पट्टियों को रेगमाल से साफ़ करके 1 M ZnSO₄ और 1 M CuSO₄ में डुबोएँ।', 'ಪಟ್ಟಿಗಳನ್ನು ಮರಳುಕಾಗದದಿಂದ ಸ್ವಚ್ಛಗೊಳಿಸಿ 1 M ZnSO₄ ಮತ್ತು 1 M CuSO₄ ನಲ್ಲಿ ಮುಳುಗಿಸಿ.'),
               W('Join the beakers with the salt bridge and connect the voltmeter (Cu to +).', 'बीकरों को लवण सेतु से जोड़ें और वोल्टमीटर लगाएँ (Cu को + से)।', 'ಬೀಕರ್‌ಗಳನ್ನು ಉಪ್ಪಿನ ಸೇತುವೆಯಿಂದ ಜೋಡಿಸಿ ವೋಲ್ಟ್‌ಮೀಟರ್ ಸಂಪರ್ಕಿಸಿ (Cu ಅನ್ನು + ಗೆ).'),
               W('Record the EMF.', 'विद्युत वाहक बल लिखें।', 'emf ದಾಖಲಿಸಿ.'),
               W('Replace the ZnSO₄ with 0.1, 0.01 and 0.001 M solutions, then vary CuSO₄, recording each time.', 'ZnSO₄ को 0.1, 0.01 और 0.001 M विलयनों से बदलें, फिर CuSO₄ बदलें, हर बार लिखें।', 'ZnSO₄ ಅನ್ನು 0.1, 0.01 ಮತ್ತು 0.001 M ದ್ರಾವಣಗಳಿಂದ ಬದಲಿಸಿ, ನಂತರ CuSO₄ ಬದಲಿಸಿ, ಪ್ರತಿ ಬಾರಿ ದಾಖಲಿಸಿ.'),
               W('Plot E against log([Zn²⁺]/[Cu²⁺]) and compare the slope with −0.0296 V.', 'E और log([Zn²⁺]/[Cu²⁺]) का ग्राफ़ बनाएँ और प्रवणता की तुलना −0.0296 V से करें।', 'E ಮತ್ತು log([Zn²⁺]/[Cu²⁺]) ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರನ್ನು −0.0296 V ನೊಂದಿಗೆ ಹೋಲಿಸಿ.')],
        precautions=[W('Clean the electrodes before every reading.', 'हर पाठ्यांक से पहले इलेक्ट्रोड साफ़ करें।', 'ಪ್ರತಿ ಓದಿಗೂ ಮೊದಲು ವಿದ್ಯುದ್ವಾರಗಳನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸಿ.'), W('Use a fresh salt bridge and rinse it between solutions.', 'नया लवण सेतु लें और विलयनों के बीच उसे धोएँ।', 'ಹೊಸ ಉಪ್ಪಿನ ಸೇತುವೆ ಬಳಸಿ ದ್ರಾವಣಗಳ ನಡುವೆ ತೊಳೆಯಿರಿ.'), W('Read the voltmeter quickly so the concentrations do not change.', 'वोल्टमीटर जल्दी पढ़ें ताकि सांद्रताएँ न बदलें।', 'ಸಾಂದ್ರತೆ ಬದಲಾಗದಂತೆ ವೋಲ್ಟ್‌ಮೀಟರ್ ಬೇಗ ಓದಿ.')],
        conclusion=W('The EMF falls as [Zn²⁺]/[Cu²⁺] rises, in a straight line against the log of the ratio with slope near −0.0296 V, as the Nernst equation predicts for n = 2.', 'EMF, [Zn²⁺]/[Cu²⁺] बढ़ने पर घटता है, अनुपात के log के साथ लगभग −0.0296 V प्रवणता की सीधी रेखा में, जैसा n = 2 के लिए नर्न्स्ट समीकरण बताता है।', '[Zn²⁺]/[Cu²⁺] ಏರಿದಂತೆ emf ಇಳಿಯುತ್ತದೆ, ಅನುಪಾತದ log ವಿರುದ್ಧ ಸುಮಾರು −0.0296 V ಇಳಿಜಾರಿನ ಸರಳರೇಖೆಯಲ್ಲಿ, n = 2 ಗೆ ನರ್ನ್‌ಸ್ಟ್ ಸಮೀಕರಣ ಹೇಳುವಂತೆ.'),
        viva=[Q(W('What does the salt bridge do?', 'लवण सेतु क्या करता है?', 'ಉಪ್ಪಿನ ಸೇತುವೆ ಏನು ಮಾಡುತ್ತದೆ?'), W('It completes the circuit and keeps both solutions electrically neutral.', 'यह परिपथ पूरा करता है और दोनों विलयनों को विद्युत रूप से उदासीन रखता है।', 'ಅದು ಮಂಡಲ ಪೂರ್ಣಗೊಳಿಸಿ ಎರಡೂ ದ್ರಾವಣಗಳನ್ನು ವಿದ್ಯುತ್ ತಟಸ್ಥವಾಗಿಡುತ್ತದೆ.')),
              Q(W('Which electrode is the anode?', 'कौन सा इलेक्ट्रोड ऐनोड है?', 'ಯಾವ ವಿದ್ಯುದ್ವಾರ ಆನೋಡ್?'), W('Zinc: oxidation, Zn → Zn²⁺ + 2e⁻, happens there.', 'जिंक: वहाँ ऑक्सीकरण Zn → Zn²⁺ + 2e⁻ होता है।', 'ಸತು: ಅಲ್ಲಿ ಉತ್ಕರ್ಷಣ Zn → Zn²⁺ + 2e⁻ ನಡೆಯುತ್ತದೆ.')),
              Q(W('What is E° for the Daniell cell?', 'डेनियल सेल का E° क्या है?', 'ಡೇನಿಯಲ್ ಕೋಶದ E° ಎಷ್ಟು?'), W('1.10 V = 0.34 − (−0.76) V.', '1.10 V = 0.34 − (−0.76) V.', '1.10 V = 0.34 − (−0.76) V.')),
              Q(W('Why use a high-resistance voltmeter?', 'उच्च प्रतिरोध वोल्टमीटर क्यों?', 'ಹೆಚ್ಚಿನ ರೋಧದ ವೋಲ್ಟ್‌ಮೀಟರ್ ಏಕೆ?'), W('So almost no current flows and the EMF, not a terminal voltage, is measured.', 'ताकि लगभग कोई धारा न बहे और टर्मिनल वोल्टता नहीं, EMF मापा जाए।', 'ಬಹುತೇಕ ಪ್ರವಾಹ ಹರಿಯದೆ, ತುದಿ ವೋಲ್ಟೇಜ್ ಅಲ್ಲ, emf ಅಳೆಯಲು.')),
              Q(W('What happens to E as the cell runs?', 'सेल चलने पर E का क्या होता है?', 'ಕೋಶ ಓಡುವಂತೆ E ಏನಾಗುತ್ತದೆ?'), W('[Zn²⁺] rises and [Cu²⁺] falls, so E drops towards zero at equilibrium.', '[Zn²⁺] बढ़ता और [Cu²⁺] घटता है, अतः साम्य पर E शून्य की ओर गिरता है।', '[Zn²⁺] ಏರಿ [Cu²⁺] ಇಳಿಯುತ್ತದೆ; ಸಮತೋಲನದಲ್ಲಿ E ಶೂನ್ಯದತ್ತ ಇಳಿಯುತ್ತದೆ.'))])

    lab(id='functional-group-tests', bench='spot-test', setup={'kit': 'organic'}, **puc2,
        keywords=['functional groups', 'organic compounds', 'alcohols phenols and ethers', 'aldehydes ketones and carboxylic acids', 'amines', 'tollens', 'fehling', '2,4-dnp', 'carbylamine', 'unsaturation'],
        title=W('Tests for functional groups in organic compounds', 'कार्बनिक यौगिकों में क्रियात्मक समूहों के परीक्षण', 'ಸಾವಯವ ಸಂಯುಕ್ತಗಳಲ್ಲಿ ಕ್ರಿಯಾತ್ಮಕ ಗುಂಪುಗಳ ಪರೀಕ್ಷೆಗಳು'),
        summary=W('Test compounds A–G with bromine water, ceric ammonium nitrate, FeCl₃, 2,4-DNP, Tollens’, Fehling’s, NaHCO₃ and the carbylamine and azo-dye tests.', 'यौगिक A–G को ब्रोमीन जल, सेरिक अमोनियम नाइट्रेट, FeCl₃, 2,4-DNP, टॉलेन्स, फ़ेहलिंग, NaHCO₃ और कार्बिलऐमीन तथा ऐज़ो-रंजक परीक्षणों से जाँचें।', 'ಸಂಯುಕ್ತ A–G ಅನ್ನು ಬ್ರೋಮಿನ್ ನೀರು, ಸೆರಿಕ್ ಅಮೋನಿಯಂ ನೈಟ್ರೇಟ್, FeCl₃, 2,4-DNP, ಟೊಲೆನ್ಸ್, ಫೆಹ್ಲಿಂಗ್, NaHCO₃ ಮತ್ತು ಕಾರ್ಬಿಲಮೀನ್ ಹಾಗೂ ಅಜೋ ವರ್ಣ ಪರೀಕ್ಷೆಗಳಿಂದ ಪರೀಕ್ಷಿಸಿ.'),
        aim=W('To identify the functional groups present in given organic compounds: unsaturation, alcoholic, phenolic, aldehydic, ketonic, carboxylic and amino groups.', 'दिए गए कार्बनिक यौगिकों में उपस्थित क्रियात्मक समूहों की पहचान करना: असंतृप्ति, ऐल्कोहॉलिक, फ़ीनॉलिक, ऐल्डिहाइडिक, कीटोनिक, कार्बोक्सिलिक और ऐमीनो समूह।', 'ನೀಡಿದ ಸಾವಯವ ಸಂಯುಕ್ತಗಳಲ್ಲಿನ ಕ್ರಿಯಾತ್ಮಕ ಗುಂಪುಗಳನ್ನು ಗುರುತಿಸುವುದು: ಅಪರ್ಯಾಪ್ತತೆ, ಆಲ್ಕೊಹಾಲಿಕ್, ಫೀನಾಲಿಕ್, ಆಲ್ಡಿಹೈಡಿಕ್, ಕೀಟೋನಿಕ್, ಕಾರ್ಬಾಕ್ಸಿಲಿಕ್ ಮತ್ತು ಅಮೈನೋ ಗುಂಪುಗಳು.'),
        principle=W('Each functional group reacts with a particular reagent to give a colour, a precipitate, a gas or a smell: C=C decolourises bromine water; –OH of alcohols gives red with ceric ammonium nitrate; phenols give violet with FeCl₃; C=O gives an orange precipitate with 2,4-DNP; only aldehydes reduce Tollens’ and Fehling’s reagents; –COOH liberates CO₂ from NaHCO₃; primary amines give the carbylamine smell.', 'प्रत्येक क्रियात्मक समूह किसी विशेष अभिकर्मक से रंग, अवक्षेप, गैस या गंध देता है: C=C ब्रोमीन जल को रंगहीन करता है; ऐल्कोहॉल का –OH सेरिक अमोनियम नाइट्रेट से लाल रंग देता है; फ़ीनॉल FeCl₃ से बैंगनी रंग देते हैं; C=O 2,4-DNP से नारंगी अवक्षेप देता है; केवल ऐल्डिहाइड टॉलेन्स और फ़ेहलिंग अभिकर्मकों को अपचयित करते हैं; –COOH, NaHCO₃ से CO₂ मुक्त करता है; प्राथमिक ऐमीन कार्बिलऐमीन गंध देते हैं।', 'ಪ್ರತಿ ಕ್ರಿಯಾತ್ಮಕ ಗುಂಪು ನಿರ್ದಿಷ್ಟ ಕಾರಕದೊಂದಿಗೆ ಬಣ್ಣ, ಅವಕ್ಷೇಪ, ಅನಿಲ ಅಥವಾ ವಾಸನೆ ನೀಡುತ್ತದೆ: C=C ಬ್ರೋಮಿನ್ ನೀರಿನ ಬಣ್ಣ ತೆಗೆಯುತ್ತದೆ; ಆಲ್ಕೊಹಾಲ್‌ಗಳ –OH ಸೆರಿಕ್ ಅಮೋನಿಯಂ ನೈಟ್ರೇಟ್‌ನೊಂದಿಗೆ ಕೆಂಪು; ಫೀನಾಲ್‌ಗಳು FeCl₃ ನೊಂದಿಗೆ ನೇರಳೆ; C=O 2,4-DNP ಯೊಂದಿಗೆ ಕಿತ್ತಳೆ ಅವಕ್ಷೇಪ; ಆಲ್ಡಿಹೈಡ್‌ಗಳು ಮಾತ್ರ ಟೊಲೆನ್ಸ್ ಮತ್ತು ಫೆಹ್ಲಿಂಗ್ ಕಾರಕಗಳನ್ನು ಅಪಕರ್ಷಿಸುತ್ತವೆ; –COOH NaHCO₃ ನಿಂದ CO₂ ಬಿಡುಗಡೆ ಮಾಡುತ್ತದೆ; ಪ್ರಾಥಮಿಕ ಅಮೀನ್‌ಗಳು ಕಾರ್ಬಿಲಮೀನ್ ವಾಸನೆ ನೀಡುತ್ತವೆ.'),
        apparatus=[TUBES, W('Organic compounds A–G', 'कार्बनिक यौगिक A–G', 'ಸಾವಯವ ಸಂಯುಕ್ತಗಳು A–G'), W('Reagents for each test', 'हर परीक्षण के अभिकर्मक', 'ಪ್ರತಿ ಪರೀಕ್ಷೆಯ ಕಾರಕಗಳು'), W('Water bath', 'जल ऊष्मक', 'ನೀರಿನ ಸ್ನಾನಪಾತ್ರೆ')],
        steps=[W('Note the physical state, colour and smell of the compound.', 'यौगिक की भौतिक अवस्था, रंग और गंध लिखें।', 'ಸಂಯುಕ್ತದ ಭೌತ ಸ್ಥಿತಿ, ಬಣ್ಣ ಮತ್ತು ವಾಸನೆ ಬರೆಯಿರಿ.'),
               W('Test for unsaturation with bromine water and for –COOH with NaHCO₃.', 'असंतृप्ति के लिए ब्रोमीन जल और –COOH के लिए NaHCO₃ से परीक्षण करें।', 'ಅಪರ್ಯಾಪ್ತತೆಗೆ ಬ್ರೋಮಿನ್ ನೀರು ಮತ್ತು –COOH ಗೆ NaHCO₃ ನಿಂದ ಪರೀಕ್ಷಿಸಿ.'),
               W('Test for –OH: ceric ammonium nitrate (alcohol) and neutral FeCl₃ (phenol).', '–OH के लिए परीक्षण: सेरिक अमोनियम नाइट्रेट (ऐल्कोहॉल) और उदासीन FeCl₃ (फ़ीनॉल)।', '–OH ಗೆ ಪರೀಕ್ಷೆ: ಸೆರಿಕ್ ಅಮೋನಿಯಂ ನೈಟ್ರೇಟ್ (ಆಲ್ಕೊಹಾಲ್) ಮತ್ತು ತಟಸ್ಥ FeCl₃ (ಫೀನಾಲ್).'),
               W('Test for C=O with 2,4-DNP; if positive, use Tollens’ and Fehling’s for an aldehyde and nitroprusside for a ketone.', 'C=O के लिए 2,4-DNP से परीक्षण करें; धनात्मक हो तो ऐल्डिहाइड के लिए टॉलेन्स और फ़ेहलिंग तथा कीटोन के लिए नाइट्रोप्रुसाइड लें।', 'C=O ಗೆ 2,4-DNP ಯಿಂದ ಪರೀಕ್ಷಿಸಿ; ಧನಾತ್ಮಕವಾದರೆ ಆಲ್ಡಿಹೈಡ್‌ಗೆ ಟೊಲೆನ್ಸ್ ಮತ್ತು ಫೆಹ್ಲಿಂಗ್, ಕೀಟೋನ್‌ಗೆ ನೈಟ್ರೋಪ್ರುಸೈಡ್ ಬಳಸಿ.'),
               W('Test for –NH₂ by the carbylamine test and the azo-dye test.', '–NH₂ के लिए कार्बिलऐमीन परीक्षण और ऐज़ो-रंजक परीक्षण करें।', '–NH₂ ಗೆ ಕಾರ್ಬಿಲಮೀನ್ ಮತ್ತು ಅಜೋ ವರ್ಣ ಪರೀಕ್ಷೆ ಮಾಡಿ.')],
        precautions=[SMALL, W('Do the carbylamine test in a fume cupboard: isocyanides are poisonous.', 'कार्बिलऐमीन परीक्षण धूम कक्ष में करें: आइसोसायनाइड विषैले होते हैं।', 'ಕಾರ್ಬಿಲಮೀನ್ ಪರೀಕ್ಷೆಯನ್ನು ಧೂಮ ಕೋಣೆಯಲ್ಲಿ ಮಾಡಿ: ಐಸೋಸೈನೈಡ್‌ಗಳು ವಿಷಕಾರಿ.'), W('Warm Tollens’ reagent in a water bath, never over a flame, and discard it at once.', 'टॉलेन्स अभिकर्मक को जल ऊष्मक में गर्म करें, कभी ज्वाला पर नहीं, और तुरंत फेंक दें।', 'ಟೊಲೆನ್ಸ್ ಕಾರಕವನ್ನು ನೀರಿನ ಸ್ನಾನಪಾತ್ರೆಯಲ್ಲಿ ಬಿಸಿಮಾಡಿ, ಜ್ವಾಲೆಯ ಮೇಲೆ ಎಂದೂ ಅಲ್ಲ; ತಕ್ಷಣ ಎಸೆಯಿರಿ.')],
        conclusion=W('Each compound gives the characteristic test of one functional group: A an alkene, B an alcohol, C a phenol, D an aldehyde, E a ketone, F a carboxylic acid and G an aromatic primary amine.', 'प्रत्येक यौगिक एक क्रियात्मक समूह का विशिष्ट परीक्षण देता है: A ऐल्कीन, B ऐल्कोहॉल, C फ़ीनॉल, D ऐल्डिहाइड, E कीटोन, F कार्बोक्सिलिक अम्ल और G ऐरोमैटिक प्राथमिक ऐमीन।', 'ಪ್ರತಿ ಸಂಯುಕ್ತ ಒಂದು ಕ್ರಿಯಾತ್ಮಕ ಗುಂಪಿನ ವಿಶಿಷ್ಟ ಪರೀಕ್ಷೆ ನೀಡುತ್ತದೆ: A ಆಲ್ಕೀನ್, B ಆಲ್ಕೊಹಾಲ್, C ಫೀನಾಲ್, D ಆಲ್ಡಿಹೈಡ್, E ಕೀಟೋನ್, F ಕಾರ್ಬಾಕ್ಸಿಲಿಕ್ ಆಮ್ಲ ಮತ್ತು G ಆರೋಮ್ಯಾಟಿಕ್ ಪ್ರಾಥಮಿಕ ಅಮೀನ್.'),
        viva=[Q(W('Why do aldehydes but not ketones reduce Tollens’ reagent?', 'ऐल्डिहाइड टॉलेन्स अभिकर्मक को अपचयित करते हैं पर कीटोन नहीं, क्यों?', 'ಆಲ್ಡಿಹೈಡ್‌ಗಳು ಟೊಲೆನ್ಸ್ ಕಾರಕವನ್ನು ಅಪಕರ್ಷಿಸುತ್ತವೆ, ಕೀಟೋನ್‌ಗಳು ಏಕೆ ಇಲ್ಲ?'), W('The aldehyde has an H on the carbonyl carbon and is easily oxidised to an acid.', 'ऐल्डिहाइड के कार्बोनिल कार्बन पर H होता है और वह आसानी से अम्ल में ऑक्सीकृत हो जाता है।', 'ಆಲ್ಡಿಹೈಡ್‌ನ ಕಾರ್ಬೊನಿಲ್ ಇಂಗಾಲದ ಮೇಲೆ H ಇದೆ; ಅದು ಸುಲಭವಾಗಿ ಆಮ್ಲವಾಗಿ ಉತ್ಕರ್ಷಣಗೊಳ್ಳುತ್ತದೆ.')),
              Q(W('What is Tollens’ reagent?', 'टॉलेन्स अभिकर्मक क्या है?', 'ಟೊಲೆನ್ಸ್ ಕಾರಕ ಎಂದರೇನು?'), W('Ammoniacal silver nitrate, [Ag(NH₃)₂]⁺.', 'अमोनियामय सिल्वर नाइट्रेट, [Ag(NH₃)₂]⁺।', 'ಅಮೋನಿಯಾಯುಕ್ತ ಸಿಲ್ವರ್ ನೈಟ್ರೇಟ್, [Ag(NH₃)₂]⁺.')),
              Q(W('Which amines give the carbylamine test?', 'कौन से ऐमीन कार्बिलऐमीन परीक्षण देते हैं?', 'ಯಾವ ಅಮೀನ್‌ಗಳು ಕಾರ್ಬಿಲಮೀನ್ ಪರೀಕ್ಷೆ ನೀಡುತ್ತವೆ?'), W('Only primary amines, aliphatic or aromatic.', 'केवल प्राथमिक ऐमीन, ऐलिफ़ैटिक या ऐरोमैटिक।', 'ಪ್ರಾಥಮಿಕ ಅಮೀನ್‌ಗಳು ಮಾತ್ರ, ಅಲಿಫ್ಯಾಟಿಕ್ ಅಥವಾ ಆರೋಮ್ಯಾಟಿಕ್.')),
              Q(W('Why is phenol acidic but does not react with NaHCO₃?', 'फ़ीनॉल अम्लीय है पर NaHCO₃ से अभिक्रिया क्यों नहीं करता?', 'ಫೀನಾಲ್ ಆಮ್ಲೀಯ, ಆದರೂ NaHCO₃ ನೊಂದಿಗೆ ಏಕೆ ವರ್ತಿಸುವುದಿಲ್ಲ?'), W('It is a weaker acid than carbonic acid.', 'यह कार्बोनिक अम्ल से दुर्बल अम्ल है।', 'ಅದು ಕಾರ್ಬಾನಿಕ್ ಆಮ್ಲಕ್ಕಿಂತ ದುರ್ಬಲ ಆಮ್ಲ.')),
              Q(W('What does 2,4-DNP detect?', '2,4-DNP क्या पहचानता है?', '2,4-DNP ಏನನ್ನು ಪತ್ತೆಹಚ್ಚುತ್ತದೆ?'), W('The carbonyl group of both aldehydes and ketones.', 'ऐल्डिहाइड और कीटोन दोनों का कार्बोनिल समूह।', 'ಆಲ್ಡಿಹೈಡ್ ಮತ್ತು ಕೀಟೋನ್ ಎರಡರ ಕಾರ್ಬೊನಿಲ್ ಗುಂಪು.'))])

    lab(id='lassaigne-test', bench='spot-test', setup={'kit': 'lassaigne'}, **puc1,
        keywords=["lassaigne's test", 'detection of elements', 'nitrogen', 'sulphur', 'halogens', 'sodium fusion extract', 'organic chemistry some basic principles and techniques'],
        title=W("Lassaigne's test for nitrogen, sulphur and halogens", 'नाइट्रोजन, सल्फ़र और हैलोजन के लिए लैसाने परीक्षण', 'ಸಾರಜನಕ, ಗಂಧಕ ಮತ್ತು ಹ್ಯಾಲೊಜೆನ್‌ಗಳಿಗೆ ಲಸ್ಸೈನ್ ಪರೀಕ್ಷೆ'),
        summary=W('Test the sodium fusion extracts of compounds P1–P5 for nitrogen, sulphur and chlorine.', 'यौगिकों P1–P5 के सोडियम संगलन निष्कर्षों में नाइट्रोजन, सल्फ़र और क्लोरीन का परीक्षण करें।', 'ಸಂಯುಕ್ತ P1–P5 ರ ಸೋಡಿಯಂ ಸಮ್ಮಿಳನ ಸಾರಗಳಲ್ಲಿ ಸಾರಜನಕ, ಗಂಧಕ ಮತ್ತು ಕ್ಲೋರಿನ್ ಪರೀಕ್ಷಿಸಿ.'),
        aim=W('To detect nitrogen, sulphur and halogens in organic compounds by Lassaigne’s test.', 'लैसाने परीक्षण से कार्बनिक यौगिकों में नाइट्रोजन, सल्फ़र और हैलोजन का पता लगाना।', 'ಲಸ್ಸೈನ್ ಪರೀಕ್ಷೆಯಿಂದ ಸಾವಯವ ಸಂಯುಕ್ತಗಳಲ್ಲಿ ಸಾರಜನಕ, ಗಂಧಕ ಮತ್ತು ಹ್ಯಾಲೊಜೆನ್‌ಗಳನ್ನು ಪತ್ತೆಹಚ್ಚುವುದು.'),
        principle=W('Fusing with sodium turns covalent N, S and halogens into ionic NaCN, Na₂S and NaX. CN⁻ gives Prussian blue with FeSO₄ and FeCl₃; S²⁻ gives violet with nitroprusside and black PbS; X⁻ gives a silver halide precipitate; N and S together give NaSCN, blood-red with FeCl₃.', 'सोडियम के साथ संगलन सहसंयोजी N, S और हैलोजन को आयनिक NaCN, Na₂S और NaX में बदल देता है। CN⁻ FeSO₄ और FeCl₃ से प्रशियन नीला देता है; S²⁻ नाइट्रोप्रुसाइड से बैंगनी और काला PbS देता है; X⁻ सिल्वर हैलाइड अवक्षेप देता है; N और S साथ में NaSCN देते हैं, जो FeCl₃ से रक्त-लाल होता है।', 'ಸೋಡಿಯಂನೊಂದಿಗೆ ಸಮ್ಮಿಳನ ಸಹವೇಲೆನ್ಸೀಯ N, S ಮತ್ತು ಹ್ಯಾಲೊಜೆನ್‌ಗಳನ್ನು ಅಯಾನಿಕ NaCN, Na₂S ಮತ್ತು NaX ಆಗಿ ಮಾಡುತ್ತದೆ. CN⁻ FeSO₄ ಮತ್ತು FeCl₃ ನೊಂದಿಗೆ ಪ್ರಷ್ಯನ್ ನೀಲಿ; S²⁻ ನೈಟ್ರೋಪ್ರುಸೈಡ್‌ನೊಂದಿಗೆ ನೇರಳೆ ಮತ್ತು ಕಪ್ಪು PbS; X⁻ ಸಿಲ್ವರ್ ಹ್ಯಾಲೈಡ್ ಅವಕ್ಷೇಪ; N ಮತ್ತು S ಒಟ್ಟಿಗೆ NaSCN, FeCl₃ ನೊಂದಿಗೆ ರಕ್ತ-ಕೆಂಪು.'),
        apparatus=[W('Fusion tubes and sodium metal', 'फ़्यूज़न नलियाँ और सोडियम धातु', 'ಫ್ಯೂಷನ್ ನಳಿಕೆಗಳು ಮತ್ತು ಸೋಡಿಯಂ ಲೋಹ'), W('China dish with distilled water', 'आसुत जल सहित चीनी मिट्टी की प्याली', 'ಬಟ್ಟಿ ನೀರಿನ ಪಿಂಗಾಣಿ ಬಟ್ಟಲು'), TUBES, W('FeSO₄, FeCl₃, sodium nitroprusside, lead acetate, AgNO₃, HNO₃', 'FeSO₄, FeCl₃, सोडियम नाइट्रोप्रुसाइड, लेड ऐसीटेट, AgNO₃, HNO₃', 'FeSO₄, FeCl₃, ಸೋಡಿಯಂ ನೈಟ್ರೋಪ್ರುಸೈಡ್, ಲೆಡ್ ಅಸಿಟೇಟ್, AgNO₃, HNO₃')],
        steps=[W('Heat a small piece of sodium with a little compound in a fusion tube until red hot.', 'फ़्यूज़न नली में सोडियम के छोटे टुकड़े को थोड़े यौगिक के साथ लाल तप्त होने तक गर्म करें।', 'ಫ್ಯೂಷನ್ ನಳಿಕೆಯಲ್ಲಿ ಸಣ್ಣ ಸೋಡಿಯಂ ತುಂಡನ್ನು ಸ್ವಲ್ಪ ಸಂಯುಕ್ತದೊಂದಿಗೆ ಕೆಂಪಾಗಿ ಕಾಯುವವರೆಗೆ ಬಿಸಿಮಾಡಿ.'),
               W('Plunge the hot tube into distilled water, boil, and filter: this is the sodium fusion extract.', 'गर्म नली को आसुत जल में डुबोएँ, उबालें और छानें: यह सोडियम संगलन निष्कर्ष है।', 'ಬಿಸಿ ನಳಿಕೆಯನ್ನು ಬಟ್ಟಿ ನೀರಿನಲ್ಲಿ ಮುಳುಗಿಸಿ, ಕುದಿಸಿ, ಸೋಸಿ: ಇದು ಸೋಡಿಯಂ ಸಮ್ಮಿಳನ ಸಾರ.'),
               W('Nitrogen: boil the extract with FeSO₄, add FeCl₃ and dilute H₂SO₄.', 'नाइट्रोजन: निष्कर्ष को FeSO₄ के साथ उबालें, FeCl₃ और तनु H₂SO₄ डालें।', 'ಸಾರಜನಕ: ಸಾರವನ್ನು FeSO₄ ನೊಂದಿಗೆ ಕುದಿಸಿ, FeCl₃ ಮತ್ತು ದುರ್ಬಲ H₂SO₄ ಸೇರಿಸಿ.'),
               W('Sulphur: add sodium nitroprusside, or acetic acid and lead acetate.', 'सल्फ़र: सोडियम नाइट्रोप्रुसाइड, या ऐसीटिक अम्ल और लेड ऐसीटेट डालें।', 'ಗಂಧಕ: ಸೋಡಿಯಂ ನೈಟ್ರೋಪ್ರುಸೈಡ್, ಅಥವಾ ಅಸಿಟಿಕ್ ಆಮ್ಲ ಮತ್ತು ಲೆಡ್ ಅಸಿಟೇಟ್ ಸೇರಿಸಿ.'),
               W('Halogens: boil with dilute HNO₃, then add AgNO₃.', 'हैलोजन: तनु HNO₃ के साथ उबालें, फिर AgNO₃ डालें।', 'ಹ್ಯಾಲೊಜೆನ್: ದುರ್ಬಲ HNO₃ ನೊಂದಿಗೆ ಕುದಿಸಿ, ನಂತರ AgNO₃ ಸೇರಿಸಿ.')],
        precautions=[W('Handle sodium with forceps; keep it away from water until the fusion.', 'सोडियम को चिमटी से पकड़ें; संगलन तक उसे पानी से दूर रखें।', 'ಸೋಡಿಯಂ ಅನ್ನು ಚಿಮುಟದಿಂದ ಹಿಡಿಯಿರಿ; ಸಮ್ಮಿಳನದವರೆಗೆ ನೀರಿನಿಂದ ದೂರವಿಡಿ.'), W('Boil off CN⁻ and S²⁻ with HNO₃ before the halogen test.', 'हैलोजन परीक्षण से पहले HNO₃ से CN⁻ और S²⁻ उबालकर निकाल दें।', 'ಹ್ಯಾಲೊಜೆನ್ ಪರೀಕ್ಷೆಗೆ ಮೊದಲು HNO₃ ನಿಂದ CN⁻ ಮತ್ತು S²⁻ ಕುದಿಸಿ ತೆಗೆಯಿರಿ.'), POINT],
        conclusion=W('The extracts show nitrogen in P1, nitrogen and sulphur in P2 and P4, and chlorine in P3; P5 contains none of them.', 'निष्कर्ष P1 में नाइट्रोजन, P2 और P4 में नाइट्रोजन तथा सल्फ़र, और P3 में क्लोरीन दिखाते हैं; P5 में इनमें से कोई नहीं।', 'ಸಾರಗಳು P1 ರಲ್ಲಿ ಸಾರಜನಕ, P2 ಮತ್ತು P4 ರಲ್ಲಿ ಸಾರಜನಕ ಹಾಗೂ ಗಂಧಕ, P3 ರಲ್ಲಿ ಕ್ಲೋರಿನ್ ತೋರಿಸುತ್ತವೆ; P5 ನಲ್ಲಿ ಯಾವುದೂ ಇಲ್ಲ.'),
        viva=[Q(W('Why is the compound fused with sodium?', 'यौगिक को सोडियम के साथ क्यों संगलित करते हैं?', 'ಸಂಯುಕ್ತವನ್ನು ಸೋಡಿಯಂನೊಂದಿಗೆ ಏಕೆ ಸಮ್ಮಿಳನ ಮಾಡುತ್ತಾರೆ?'), W('To turn the covalently bound elements into ions that can be tested in water.', 'सहसंयोजी रूप से बंधे तत्वों को आयनों में बदलने के लिए जिन्हें पानी में जाँचा जा सके।', 'ಸಹವೇಲೆನ್ಸೀಯವಾಗಿ ಬಂಧಿತ ಮೂಲಧಾತುಗಳನ್ನು ನೀರಿನಲ್ಲಿ ಪರೀಕ್ಷಿಸಬಹುದಾದ ಅಯಾನುಗಳಾಗಿ ಮಾಡಲು.')),
              Q(W('What is Prussian blue?', 'प्रशियन नीला क्या है?', 'ಪ್ರಷ್ಯನ್ ನೀಲಿ ಎಂದರೇನು?'), W('Iron(III) hexacyanoferrate(II), Fe₄[Fe(CN)₆]₃.', 'आयरन(III) हेक्सासायनोफ़ेरेट(II), Fe₄[Fe(CN)₆]₃।', 'ಐರನ್(III) ಹೆಕ್ಸಾಸೈನೊಫೆರೇಟ್(II), Fe₄[Fe(CN)₆]₃.')),
              Q(W('Why does urea not give a halogen test?', 'यूरिया हैलोजन परीक्षण क्यों नहीं देता?', 'ಯೂರಿಯಾ ಹ್ಯಾಲೊಜೆನ್ ಪರೀಕ್ಷೆ ಏಕೆ ನೀಡುವುದಿಲ್ಲ?'), W('It contains no halogen: CO(NH₂)₂.', 'इसमें कोई हैलोजन नहीं है: CO(NH₂)₂।', 'ಅದರಲ್ಲಿ ಹ್ಯಾಲೊಜೆನ್ ಇಲ್ಲ: CO(NH₂)₂.')),
              Q(W('Why boil with nitric acid before adding AgNO₃?', 'AgNO₃ डालने से पहले नाइट्रिक अम्ल से क्यों उबालते हैं?', 'AgNO₃ ಸೇರಿಸುವ ಮೊದಲು ನೈಟ್ರಿಕ್ ಆಮ್ಲದೊಂದಿಗೆ ಏಕೆ ಕುದಿಸುತ್ತಾರೆ?'), W('To destroy cyanide and sulphide, which would also precipitate with silver.', 'सायनाइड और सल्फ़ाइड नष्ट करने के लिए, जो चाँदी के साथ भी अवक्षेपित होते।', 'ಬೆಳ್ಳಿಯೊಂದಿಗೆ ಅವಕ್ಷೇಪಗೊಳ್ಳುವ ಸೈನೈಡ್ ಮತ್ತು ಸಲ್ಫೈಡ್ ನಾಶಮಾಡಲು.')),
              Q(W('What colour does a bromide give with AgNO₃?', 'ब्रोमाइड AgNO₃ से कौन सा रंग देता है?', 'ಬ್ರೋಮೈಡ್ AgNO₃ ನೊಂದಿಗೆ ಯಾವ ಬಣ್ಣ?'), W('A pale yellow precipitate, sparingly soluble in ammonia.', 'हल्का पीला अवक्षेप, अमोनिया में अल्प विलेय।', 'ತಿಳಿ ಹಳದಿ ಅವಕ್ಷೇಪ, ಅಮೋನಿಯಾದಲ್ಲಿ ಸ್ವಲ್ಪ ಕರಗುತ್ತದೆ.'))])
